import re


_ROLE_RE = re.compile(
    r"(?is)^\s*(?:Hon\.?\s*)?(?P<name>.+?)\s*,\s*"
    r"(?:(?:United States\s+|U\.S\.\s+)?(?:Chief|Senior)\s+)?"
    r"(?:United States\s+|U\.S\.\s+)?District Judge(?:,\s*|\s+)Presiding\s*[\.\*\u2020]*\s*$"
)
_MAGISTRATE_RE = re.compile(
    r"(?is)^\s*(?:Hon\.?\s*)?(?P<name>.+?)\s*,\s*"
    r"(?:United States\s+|U\.S\.\s+)?Magistrate Judge(?:,\s*|\s+)Presiding\s*[\.\*\u2020]*\s*$"
)
_BANKRUPTCY_RE = re.compile(
    r"(?is)^\s*(?:Hon\.?\s*)?(?P<name>.+?)\s*,\s*"
    r"(?:United States\s+|U\.S\.\s+)?Bankruptcy Judges?(?:,\s*|\s+)Presiding\s*[\.\*\u2020]*\s*$"
)

_ROLE_HINT_RE = re.compile(
    r"(?i)\b(?:(?:chief|senior)\s+)?district judge\b|\bmagistrate judge\b|\bbankruptcy judges?\b"
)
_NAMEISH_RE = re.compile(
    r"(?i)^\s*(?:Hon\.?\s*)?[A-Z][A-Za-z0-9.'’\-]*(?:\s+[A-Z][A-Za-z0-9.'’\-]*){0,6}\s*,?\s*$"
)
_NAME_FRAGMENT_RE = re.compile(
    r"(?i)^\s*(?:Hon\.?\s*)?[A-Z][^,\n]*(?:,\s*[^,\n]+)*(?:,\s*and| and|,|&)\s*$"
)
_NON_NAME_HINT_RE = re.compile(
    r"(?i)\b(?:appeal|appeals|district court|bankruptcy appellate panel|bankruptcy court|"
    r"court of appeals|before:|summary|opinion|argued|submitted|filed|before|"
    r"circuit judge|circuit judges|district judge|magistrate judge|bankruptcy judge|"
    r"appellant|appellee|plaintiff|defendant|panel|court|district\b|for the\b)\b"
)


def rule_presiding_district_judge(doc: dict) -> list[dict]:
    try:
        spans = []
        seen = set()

        def add_name(raw_name: str, source_item: dict) -> None:
            name = re.sub(r"(?i)^\s*Hon\.?\s*", "", raw_name or "").strip()
            name = name.strip(" \t\r\n,.;:*")
            name = re.sub(r"\s+", " ", name).strip()
            if not name:
                return
            key = name.lower()
            if key in seen:
                return
            seen.add(key)
            span = {"text": name}
            for field in ("page_no", "line_no", "paragraph_no"):
                if field in source_item:
                    span[field] = source_item[field]
            spans.append(span)

        def find_match(text: str) -> str | None:
            normalized = re.sub(r"\s+", " ", (text or "")).strip()
            if not normalized:
                return None
            for pat in (_ROLE_RE, _MAGISTRATE_RE, _BANKRUPTCY_RE):
                match = pat.match(normalized)
                if match:
                    return match.group("name")
            return None

        def scan_items(items: list[dict]) -> None:
            limit = min(len(items or []), 120)

            def is_nameish(text: str) -> bool:
                normalized = re.sub(r"\s+", " ", text or "").strip()
                if not normalized or _NON_NAME_HINT_RE.search(normalized):
                    return False
                return bool(_NAMEISH_RE.match(normalized) or _NAME_FRAGMENT_RE.match(normalized))

            for i in range(limit):
                item = items[i] or {}
                text = (item.get("text") or "").strip()
                if not text:
                    continue

                has_role_hint = bool(_ROLE_HINT_RE.search(text))
                has_presiding = "presiding" in text.lower()
                prev_text = ((items[i - 1] or {}).get("text") or "").strip() if i > 0 else ""
                next_text = ((items[i + 1] or {}).get("text") or "").strip() if i + 1 < limit else ""

                direct_name = find_match(text)
                if direct_name and not (has_role_hint or has_presiding):
                    add_name(direct_name, item)
                    continue

                candidates = []

                if prev_text and is_nameish(prev_text):
                    candidates.append((f"{prev_text} {text}", items[i - 1] or item))

                if next_text and is_nameish(next_text):
                    candidates.append((f"{text} {next_text}", item))

                if prev_text and next_text and is_nameish(prev_text):
                    candidates.append((f"{prev_text} {text} {next_text}", items[i - 1] or item))

                if prev_text and next_text and is_nameish(next_text):
                    candidates.append((f"{prev_text} {text} {next_text}", item))

                matched = False
                for candidate_text, candidate_source in candidates:
                    candidate_name = find_match(candidate_text)
                    if candidate_name:
                        add_name(candidate_name, candidate_source)
                        matched = True
                        break

                if matched:
                    continue

                if direct_name:
                    add_name(direct_name, item)

        scan_items(doc.get("lines") or [])
        scan_items(doc.get("paragraphs") or [])

        if len(spans) > 1 and not any(
            any(sep in (span.get("text") or "") for sep in (",", " and ", ";"))
            for span in spans
        ):
            aggregate_text = "; ".join(span.get("text") or "" for span in spans if span.get("text"))
            if aggregate_text:
                aggregate_key = aggregate_text.lower()
                if aggregate_key not in seen:
                    seen.add(aggregate_key)
                    aggregate_span = {"text": aggregate_text}
                    first_span = spans[0]
                    for field in ("page_no", "line_no", "paragraph_no"):
                        if field in first_span:
                            aggregate_span[field] = first_span[field]
                    spans.insert(0, aggregate_span)

        if not spans:
            full_text = re.sub(r"\s+", " ", doc.get("text") or "").strip()
            if full_text:
                for pat in (_ROLE_RE, _MAGISTRATE_RE, _BANKRUPTCY_RE):
                    match = pat.search(full_text)
                    if match:
                        add_name(match.group("name"), {})
                        break

        return spans
    except Exception:
        return []

import re


_APPEAL_LABEL = "Appeal from the United States District Court"
_STOP_LABELS = ("SUMMARY",)


def rule_us_district_court_origin(doc: dict) -> list[dict]:
    try:
        spans = []
        seen = set()

        def add_span(text: str, source_item: dict) -> None:
            cleaned = re.sub(r"\s+", " ", (text or "")).strip().rstrip(".,;:")
            if not cleaned:
                return
            key = cleaned.lower()
            if key in seen:
                return
            seen.add(key)
            span = {"text": cleaned}
            for field in ("page_no", "line_no", "paragraph_no"):
                if field in source_item:
                    span[field] = source_item[field]
            spans.append(span)

        def scan_items(items: list[dict]) -> None:
            limit = min(len(items or []), 120)
            for i in range(limit):
                item = items[i] or {}
                text = (item.get("text") or "").strip()
                if not text:
                    continue

                upper = text.upper()
                if any(upper.startswith(stop) for stop in _STOP_LABELS):
                    break

                label_pos = text.find(_APPEAL_LABEL)
                if label_pos < 0:
                    continue

                remainder = text[label_pos + len(_APPEAL_LABEL):].strip()
                if remainder:
                    # Some OCR variants keep the district line on the same row.
                    if remainder.lower().startswith("for the "):
                        add_span(remainder, item)
                        continue

                for j in range(i + 1, min(limit, i + 6)):
                    next_item = items[j] or {}
                    next_text = (next_item.get("text") or "").strip()
                    if not next_text:
                        continue

                    next_upper = next_text.upper()
                    if any(next_upper.startswith(stop) for stop in _STOP_LABELS):
                        break

                    if next_text.lower().startswith("for the "):
                        add_span(next_text, next_item)
                        break

                    # A few pages may omit the literal "for the" prefix.
                    if (
                        "judge" not in next_text.lower()
                        and re.search(r"(?i)\b(?:district|circuit)\b", next_text)
                    ):
                        add_span(next_text, next_item)
                        break

        def scan_history_items(items: list[dict]) -> None:
            for i, item in enumerate(items or []):
                text = (item or {}).get("text") or ""
                lower = text.lower()
                if "appeal" not in lower or "united states district court for the" not in lower:
                    continue

                tail = text.split("United States District Court for the", 1)[1].strip()
                if tail:
                    add_span(tail.split(",")[0].strip(), item)
                else:
                    for j in range(i + 1, min(len(items or []), i + 4)):
                        next_item = items[j] or {}
                        next_text = (next_item.get("text") or "").strip()
                        if not next_text:
                            continue
                        if "judge" in next_text.lower():
                            continue
                        if re.search(r"(?i)\bdistrict\b", next_text):
                            add_span(next_text.split(",")[0].strip(), next_item)
                            break

                for j in range(i + 1, min(len(items or []), i + 60)):
                    next_item = items[j] or {}
                    next_text = (next_item.get("text") or "").strip()
                    if not next_text:
                        continue
                    if "judge" in next_text.lower():
                        continue
                    if "united states district court for the" not in next_text.lower():
                        continue
                    district_tail = next_text.split("United States District Court for the", 1)[1].strip()
                    if district_tail:
                        add_span(district_tail.split(",")[0].strip(), next_item)

        scan_items(doc.get("lines") or [])
        scan_items(doc.get("paragraphs") or [])
        scan_history_items(doc.get("lines") or [])
        scan_history_items(doc.get("paragraphs") or [])

        if not spans:
            full_text = doc.get("text") or ""
            for match in re.finditer(re.escape(_APPEAL_LABEL), full_text):
                start = match.end()
                tail = full_text[start:start + 180]
                tail = tail.lstrip(" \t\r\n")
                line = tail.splitlines()[0].strip() if tail else ""
                if line.lower().startswith("for the "):
                    add_span(line, {})

        return spans
    except Exception:
        return []

