  "rule_name": "rule_argument_submission_date_header",
  "file": "/mnt/data/LSF/rules/court/agentic_rule_full_data_gpt54mini/all_docs/q05_on_what_date_was_the_case_argued_or_submitted_on_the_briefs/rule_argument_submission_date_header.py",
  "code": "import re\n\n\n_ARGUED_AND_SUBMITTED_RE = re.compile(\n    r\"(?i)^\\s*Argued and Submitted(?:\\s+En Banc)?\\s+\"\n    r\"(?P<date>[A-Z][a-z]+ \\d{1,2}, \\d{4})\\*?\\s*$\"\n)\n_SUBMITTED_RE = re.compile(\n    r\"(?i)^\\s*Submitted(?:\\s+on the briefs)?(?:\\s+En Banc)?\\s+\"\n    r\"(?P<date>[A-Z][a-z]+ \\d{1,2}, \\d{4})\\*?\\s*$\"\n)\n\n\ndef rule_argument_submission_date_header(doc: dict) -> list[dict]:\n    try:\n        spans = []\n        seen = set()\n\n        def add_span(date_text: str, source_item: dict) -> None:\n            cleaned = re.sub(r\"\\s+\", \" \", (date_text or \"\")).strip().rstrip(\".,;:\")\n            if not cleaned:\n                return\n            key = cleaned.lower()\n            if key in seen:\n                return\n            seen.add(key)\n            span = {\"text\": cleaned}\n            for field in (\"page_no\", \"line_no\", \"paragraph_no\"):\n                if field in source_item:\n                    span[field] = source_item[field]\n            spans.append(span)\n\n        def extract_date(text: str) -> str | None:\n            normalized = re.sub(r\"\\s+\", \" \", (text or \"\")).strip()\n            if not normalized:\n                return None\n            for pattern in (_ARGUED_AND_SUBMITTED_RE, _SUBMITTED_RE):\n                match = pattern.match(normalized)\n                if match:\n                    return match.group(\"date\")\n            return None\n\n        def scan_items(items: list[dict]) -> None:\n            limit = min(len(items or []), 80)\n            for i in range(limit):\n                item = items[i] or {}\n                text = (item.get(\"text\") or \"\").strip()\n                if not text:\n                    continue\n\n                date_text = extract_date(text)\n                if date_text:\n                    add_span(date_text, item)\n                    return\n\n                # Some OCR variants split the header across adjacent rows.\n                if i + 1 < limit:\n                    next_item = items[i + 1] or {}\n                    next_text = (next_item.get(\"text\") or \"\").strip()\n                    if next_text:\n                        combined = f\"{text} {next_text}\"\n                        date_text = extract_date(combined)\n                        if date_text:\n                            add_span(date_text, item)\n                            return\n\n        scan_items(doc.get(\"lines\") or [])\n        if not spans:\n            scan_items(doc.get(\"paragraphs\") or [])\n\n        if not spans:\n            full_text = doc.get(\"text\") or \"\"\n            for pattern in (_ARGUED_AND_SUBMITTED_RE, _SUBMITTED_RE):\n                match = pattern.search(full_text)\n                if match:\n                    add_span(match.group(\"date\"), {})\n                    break\n\n        return spans\n    except Exception:\n        return []\n",
